		skipPostDeploy:     options.skipPostDeploy,
		skipLabDirFileACLs: options.skipLabDirFileACLs,
		graph:              options.graph,
		finalizeNoop:       true,
		maxWorkers:         options.maxWorkers,
		exportTemplate:     options.exportTemplate,
	}
